import re, sys
from pathlib import Path
sys.path.insert(0, 'scripts')
from blueprint_citations import build_label_index, _active_lines
root = Path.cwd()
index = build_label_index(root)
lines = {p: _active_lines(root / p) for locs in index.values() for p in {l.path for l in locs}}
edges = {}
for label, locs in index.items():
    if not label.startswith(('lem:', 'len:', 'thm:', 'cor:', 'fact:', 'def:', 'prop:', 'rem:')):
        continue
    for loc in locs:
        body = '\\n'.join(lines[loc.path][loc.start-1:loc.end])
        deps = {d.strip() for group in re.findall(r'\\\\uses\\{(["'^}]*)'"\\}', body) for d in group.split(',')}
        edges.setdefault(label, set()).update(deps - {label})
for seed in ('thm:ms-rigidity', 'lem:qld-ms-anticommutator-original-state'):
    seen, frontier = {seed}, {seed}
    depth = 0
    print('ROOT', seed)
    while frontier:
        for node in sorted(frontier):
            loc = index[node][0]
            print(depth, node, loc.locator, 'FROM', ','.join(sorted(edges.get(node, set()) & seen)))
        frontier = {node for node, deps in edges.items() if node not in seen and deps & frontier}
        seen |= frontier
        depth += 1
    print('TOTAL', len(seen))
